public:
    vector<int> diffWaysToCompute(string expression) {
        unordered_map<string, vector<int>> memo;
        auto compute = [&](auto& self, string expr) -> vector<int> {
            if (memo.count(expr)) return memo[expr];
            vector<int> res;
            for (int i = 0; i < (int)expr.size(); i++) {
                char ch = expr[i];
                if (ch == '+' || ch == '-' || ch == '*') {
                    vector<int> left = self(self, expr.substr(0, i));
                    vector<int> right = self(self, expr.substr(i + 1));
                    for (int l : left) {
                        for (int r : right) {
                            if (ch == '+') res.push_back(l + r);
                            else if (ch == '-') res.push_back(l - r);
                            else if (ch == '*') res.push_back(l * r);
                        }
                    }
                }
            }
            if (res.empty()) {
                res.push_back(stoi(expr));
            }
            return memo[expr] = res;
        };
        return compute(compute, expression);
    }
};

class Solution {
    private Map<String, List<Integer>> memo = new HashMap<>();

    public List<Integer> diffWaysToCompute(String expression) {
        if (memo.containsKey(expression)) return memo.get(expression);
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < expression.length(); i++) {
            char ch = expression.charAt(i);
            if (ch == '+' || ch == '-' || ch == '*') {
                List<Integer> left = diffWaysToCompute(expression.substring(0, i));
                List<Integer> right = diffWaysToCompute(expression.substring(i + 1));
                for (int l : left) {
                    for (int r : right) {
                        if (ch == '+') res.add(l + r);
                        else if (ch == '-') res.add(l - r);
                        else if (ch == '*') res.add(l * r);
                    }
                }
            }
        }
        if (res.isEmpty()) {
            res.add(Integer.parseInt(expression));
        }
        memo.put(expression, res);
        return res;
    }
}

var diffWaysToCompute = function(expression) {
    const memo = new Map();
    const compute = (expr) => {
        if (memo.has(expr)) return memo.get(expr);
        const res = [];
        for (let i = 0; i < expr.length; i++) {
            const ch = expr[i];
            if (ch === '+' || ch === '-' || ch === '*') {
                const left = compute(expr.slice(0, i));
                const right = compute(expr.slice(i + 1));
                for (const l of left) {
                    for (const r of right) {
                        if (ch === '+') res.push(l + r);
                        else if (ch === '-') res.push(l - r);
                        else if (ch === '*') res.push(l * r);
                    }
                }
            }
        }
        if (res.length === 0) {
            res.push(Number(expr));
        }
        memo.set(expr, res);
        return res;
    };
    return compute(expression);
